		return errSessionExpired
	})
	if calls != 1 {
		t.Fatalf("op should not retry on cross-server 401, ran %d times", calls)
	}
	if !errors.Is(err, errSessionExpired) {
		t.Fatalf("expected errSessionExpired bubbled, got %v", err)
	}
	if sess.Token != "tokA" {
