func TestWrapDEKRoundTrip(t *testing.T) {
	mk, _, err := SetupPasswordless()
	if err != nil {
		t.Fatal(err)
	}
	defer mk.Wipe()

	password := []byte("test-password")
	salt, dekCT, dekNonce, params, err := WrapDEK(mk.Key(), password)
	if err != nil {
		t.Fatalf("WrapDEK: %v", err)
	}

	// Build a verification record to unlock.
	sentinelCT, sentinelNonce, err := crypto.Encrypt([]byte(sentinel), mk.Key())
	if err != nil {
		t.Fatal(err)
	}

	rec := &VerificationRecord{
		Sentinel:      sentinelCT,
		SentinelNonce: sentinelNonce,
		DEKCiphertext: dekCT,
		DEKNonce:      dekNonce,
		Salt:          salt,
		Params:        params,
	}

	mk2, err := Unlock(password, rec)
	if err != nil {
		t.Fatalf("Unlock after WrapDEK: %v", err)
	}
	defer mk2.Wipe()

	if string(mk.Key()) != string(mk2.Key()) {
		t.Fatal("DEK mismatch after WrapDEK round-trip")
	}
}

func TestPasswordChangePreservesDEK(t *testing.T) {
	oldPw := []byte("old-password")
	newPw := []byte("new-password")

	mk, rec, err := SetupWithPassword(oldPw)
	if err != nil {
		t.Fatal(err)
	}
	defer mk.Wipe()

	originalDEK := make([]byte, len(mk.Key()))
	copy(originalDEK, mk.Key())

	// Re-wrap the DEK under a new password.
	salt, dekCT, dekNonce, params, err := WrapDEK(mk.Key(), newPw)
	if err != nil {
		t.Fatal(err)
	}

	// Update the verification record.
	rec.DEKCiphertext = dekCT
	rec.DEKNonce = dekNonce
	rec.Salt = salt
	rec.Params = params

	// Old password should no longer work.
	_, err = Unlock(oldPw, rec)
	if err != ErrWrongPassword {
		t.Fatalf("expected ErrWrongPassword with old password, got %v", err)
	}

	// New password should work and return the same DEK.
	mk2, err := Unlock(newPw, rec)
	if err != nil {
		t.Fatalf("Unlock with new password: %v", err)
	}
	defer mk2.Wipe()

	if string(mk2.Key()) != string(originalDEK) {
		t.Fatal("DEK changed after password change — it should be preserved")
	}
}

package oauth

import (
	"context"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"net/url"
	"testing"
	"time"
)

// helper: parse form from request body
func parseForm(t *testing.T, r *http.Request) url.Values {
	t.Helper()
	body, err := io.ReadAll(r.Body)
	if err != nil {
		t.Fatalf("reading request body: %v", err)
	}
	vals, err := url.ParseQuery(string(body))
	if err != nil {
		t.Fatalf("parsing form body: %v", err)
	}
	return vals
}

func TestExchange_HappyPath(t *testing.T) {
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		form := parseForm(t, r)
		if got := form.Get("grant_type"); got != "authorization_code" {
			t.Errorf("grant_type = %q, want authorization_code", got)
		}
		if got := form.Get("code"); got != "auth-code-123" {
			t.Errorf("code = %q, want auth-code-123", got)
		}
		if got := form.Get("redirect_uri"); got != "http://localhost/callback" {
			t.Errorf("redirect_uri = %q, want http://localhost/callback", got)
		}
		if got := form.Get("client_id"); got != "my-client" {
			t.Errorf("client_id = %q, want my-client", got)
		}
		if got := form.Get("client_secret"); got != "my-secret" {
			t.Errorf("client_secret = %q, want my-secret", got)
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{
			"access_token":  "tok",
			"token_type":    "bearer",
			"expires_in":    3600,
			"refresh_token": "ref",
		})
	}))
	defer ts.Close()

	before := time.Now()
	tok, err := Exchange(context.Background(), ExchangeConfig{
		TokenURL:     ts.URL,
		ClientID:     "my-client",
		ClientSecret: "my-secret",
		Code:         "auth-code-123",
		RedirectURI:  "http://localhost/callback",
	})
	if err != nil {
		t.Fatalf("Exchange returned error: %v", err)
	}
	if tok.AccessToken != "tok" {
		t.Errorf("AccessToken = %q, want tok", tok.AccessToken)
	}
	if tok.RefreshToken != "ref" {
		t.Errorf("RefreshToken = %q, want ref", tok.RefreshToken)
	}
	if tok.TokenType != "bearer" {
		t.Errorf("TokenType = %q, want bearer", tok.TokenType)
	}
	if tok.ExpiresIn != 3600 {
		t.Errorf("ExpiresIn = %d, want 3600", tok.ExpiresIn)
	}
	// ExpiresAt should be roughly now + 3600s
	expectedAt := before.Add(3600 * time.Second)
	if tok.ExpiresAt.Before(before) || tok.ExpiresAt.After(expectedAt.Add(5*time.Second)) {
		t.Errorf("ExpiresAt = %v, expected ~%v", tok.ExpiresAt, expectedAt)
	}
}

func TestExchange_PublicClient(t *testing.T) {
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		form := parseForm(t, r)
		if form.Get("client_secret") != "" {
			t.Error("client_secret should NOT be present for public clients")
		}
		if got := form.Get("code_verifier"); got != "my-verifier" {
			t.Errorf("code_verifier = %q, want my-verifier", got)
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{
			"access_token": "public-tok",
			"token_type":   "bearer",
			"expires_in":   1800,
		})
	}))
	defer ts.Close()

	tok, err := Exchange(context.Background(), ExchangeConfig{
		TokenURL:     ts.URL,
		ClientID:     "public-client",
		ClientSecret: "", // public client — no secret
		Code:         "code",
		RedirectURI:  "http://localhost/callback",
		CodeVerifier: "my-verifier",
	})
	if err != nil {
		t.Fatalf("Exchange returned error: %v", err)
	}
	if tok.AccessToken != "public-tok" {
