func TestRefresh_RateLimited(t *testing.T) {
	ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(429)
		w.Write([]byte("too many requests"))
	}))
	defer ts.Close()

	_, err := Refresh(context.Background(), RefreshConfig{
		TokenURL:     ts.URL,
		ClientID:     "c",
		ClientSecret: "s",
