import { describe, test } from "node:test";
import assert from "node:assert/strict";

import { formatThreadTranscript } from "./slack-transcript.js";

describe("formatThreadTranscript", () => {
  test("formats user and bot messages and strips bot mentions", () => {
    const transcript = formatThreadTranscript(
      [
        { user: "U1", text: "<@BOT> hello" },
        { user: "BOT", text: "hi there" },
      ],
      { agentName: "Agent", botUserId: "BOT" },
    );

    assert.equal(transcript, "<@U1>: hello\nAgent: hi there");
  });

  test("keeps only the most recent messages when message count is capped", () => {
    const transcript = formatThreadTranscript(
      Array.from({ length: 5 }, (_, index) => ({
        user: `U${index}`,
        text: `message ${index}`,
      })),
      { agentName: "Agent", maxMessages: 2 },
    );

    assert.match(transcript, /^\[Earlier thread context omitted for length\.\]/);
    assert.ok(!transcript.includes("message 2"));
    assert.ok(transcript.includes("message 3"));
    assert.ok(transcript.includes("message 4"));
  });

  test("keeps most recent lines within a character cap", () => {
    const transcript = formatThreadTranscript(
      [
        { user: "U1", text: "older message" },
        { user: "U2", text: "middle message" },
        { user: "U3", text: "newer message" },
      ],
      { agentName: "Agent", maxChars: 45 },
    );

    assert.match(transcript, /^\[Earlier thread context omitted for length\.\]/);
    assert.ok(!transcript.includes("older message"));
    assert.ok(transcript.includes("newer message"));
  });

  test("truncates a single oversized message", () => {
    const transcript = formatThreadTranscript(
      [{ user: "U1", text: "x".repeat(100) }],
      { agentName: "Agent", maxChars: 30, maxMessageChars: 100 },
    );

    assert.ok(transcript.length <= 30);
    assert.ok(transcript.endsWith("..."));
  });
});

import { vi } from "vitest";

interface MockResponseOptions {
  ok?: boolean;
  status?: number;
  statusText?: string;
  body?: unknown;
  headers?: Record<string, string>;
}

function buildMockResponse(response: MockResponseOptions): Response {
  const ok = response.ok ?? true;
  const status = response.status ?? (ok ? 200 : 400);
  const bodyText = typeof response.body === "string"
    ? response.body
    : JSON.stringify(response.body ?? {});
  return {
    ok,
    status,
    statusText: response.statusText ?? (ok ? "OK" : "Bad Request"),
    headers: new Headers(response.headers),
    json: () => Promise.resolve(response.body ?? {}),
    text: () => Promise.resolve(bodyText),
    arrayBuffer: () =>
      Promise.resolve(new TextEncoder().encode(bodyText).buffer),
    body: null,
  } as Response;
}

export function createMockFetch(response: MockResponseOptions) {
  return vi.fn<typeof globalThis.fetch>().mockResolvedValue(
    buildMockResponse(response),
  );
}

/** Create a mock fetch that routes by URL path substring. */
export function createRoutedMockFetch(routes: Record<string, MockResponseOptions>) {
  return vi.fn<typeof globalThis.fetch>().mockImplementation(async (input) => {
    const url = typeof input === "string" ? input : (input as Request).url;
    for (const [pattern, response] of Object.entries(routes)) {
      if (url.includes(pattern)) {
        return buildMockResponse(response);
      }
    }
    throw new Error(`Unexpected URL: ${url}`);
  });
}

import { test } from "node:test";
import assert from "node:assert/strict";

// access.ts reads AGENT_ALLOWLIST once at import, so set it before importing.
process.env.AGENT_ALLOWLIST = "Alex@example.com, robin@example.com  morgan@example.com";
const { isAllowedEmail, allowlistConfigured } = await import("./access.js");

test("allowlist is configured when the env var has entries", () => {
  assert.equal(allowlistConfigured(), true);
});

test("allows listed emails case- and whitespace-insensitively", () => {
  assert.equal(isAllowedEmail("alex@example.com"), true);
  assert.equal(isAllowedEmail("ALEX@EXAMPLE.COM"), true);
  assert.equal(isAllowedEmail("  robin@example.com "), true);
  assert.equal(isAllowedEmail("morgan@example.com"), true);
});

test("denies unlisted, empty, and missing emails when configured", () => {
  assert.equal(isAllowedEmail("stranger@example.com"), false);
  assert.equal(isAllowedEmail(""), false);
  assert.equal(isAllowedEmail(undefined), false);
  assert.equal(isAllowedEmail(null), false);
});

test("allows everyone when no allowlist is configured", async () => {
  delete process.env.AGENT_ALLOWLIST;
  const module = await import(`./access.js?unset=${Date.now()}`);
  assert.equal(module.allowlistConfigured(), false);
  assert.equal(module.isAllowedEmail("anyone@example.com"), true);
  assert.equal(module.isAllowedEmail(undefined), true);
});

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { AgentVault } from "../src/client.js";
import { AgentVaultError } from "../src/errors.js";
import { VaultClient } from "../src/vault.js";

describe("AgentVault", () => {
  const originalEnv = process.env;

  beforeEach(() => {
    process.env = { ...originalEnv };
    delete process.env.AGENT_VAULT_TOKEN;
    delete process.env.AGENT_VAULT_ADDR;
  });

  afterEach(() => {
    process.env = originalEnv;
  });

  describe("constructor", () => {
    it("creates client with explicit token", () => {
      const av = new AgentVault({ token: "test-token" });
      expect(av).toBeInstanceOf(AgentVault);
    });

    it("throws if no token in config or env", () => {
      expect(() => new AgentVault()).toThrow(AgentVaultError);
      expect(() => new AgentVault()).toThrow("Token is required");
    });

    it("reads token from AGENT_VAULT_TOKEN env var", () => {
      process.env.AGENT_VAULT_TOKEN = "env-token";
      const av = new AgentVault();
      expect(av).toBeInstanceOf(AgentVault);
    });

    it("prefers config token over env var", () => {
      process.env.AGENT_VAULT_TOKEN = "env-token";
      // Should not throw — config token takes precedence
      const av = new AgentVault({ token: "config-token" });
      expect(av).toBeInstanceOf(AgentVault);
    });

    it("reads address from AGENT_VAULT_ADDR env var", () => {
      process.env.AGENT_VAULT_TOKEN = "test-token";
      process.env.AGENT_VAULT_ADDR = "http://custom:9999";
      const av = new AgentVault();
      expect(av).toBeInstanceOf(AgentVault);
    });
  });

  describe("vault()", () => {
    it("returns a VaultClient instance", () => {
      const av = new AgentVault({ token: "test-token" });
      const vault = av.vault("my-project");
      expect(vault).toBeInstanceOf(VaultClient);
    });

    it("sets the vault name on the returned VaultClient", () => {
      const av = new AgentVault({ token: "test-token" });
      const vault = av.vault("production");
      expect(vault.name).toBe("production");
    });

    it("returns different VaultClient instances for different vaults", () => {
      const av = new AgentVault({ token: "test-token" });
      const v1 = av.vault("vault-a");
      const v2 = av.vault("vault-b");
      expect(v1).not.toBe(v2);
      expect(v1.name).toBe("vault-a");
      expect(v2.name).toBe("vault-b");
    });

    it("returns a VaultClient with sessions resource", () => {
      const av = new AgentVault({ token: "test-token" });
      const vault = av.vault("my-project");
      expect(vault.sessions).toBeDefined();
    });
  });
});

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { AgentVaultError } from "../src/errors.js";
import { VaultClient } from "../src/vault.js";
import { AgentVault } from "../src/client.js";

describe("VaultClient", () => {
  const originalEnv = process.env;

  beforeEach(() => {
    process.env = { ...originalEnv };
    delete process.env.AGENT_VAULT_TOKEN;
    delete process.env.AGENT_VAULT_ADDR;
  });

  afterEach(() => {
    process.env = originalEnv;
  });

  describe("standalone constructor", () => {
    it("creates client with explicit token", () => {
      const vault = new VaultClient({ token: "scoped-token" });
      expect(vault).toBeInstanceOf(VaultClient);
    });

    it("throws if no token in config or env", () => {
      expect(() => new VaultClient()).toThrow(AgentVaultError);
      expect(() => new VaultClient()).toThrow("Token is required");
    });

    it("reads token from AGENT_VAULT_TOKEN env var", () => {
      process.env.AGENT_VAULT_TOKEN = "env-token";
      const vault = new VaultClient();
      expect(vault).toBeInstanceOf(VaultClient);
    });

    it("has undefined name for standalone construction", () => {
      const vault = new VaultClient({ token: "scoped-token" });
      expect(vault.name).toBeUndefined();
    });

    it("has undefined sessions for standalone construction", () => {
      const vault = new VaultClient({ token: "scoped-token" });
      expect(vault.sessions).toBeUndefined();
    });

    it("has undefined services for standalone construction", () => {
      const vault = new VaultClient({ token: "scoped-token" });
      expect(vault.services).toBeUndefined();
    });

    it("has credentials resource for standalone construction", () => {
      const vault = new VaultClient({ token: "scoped-token" });
      expect(vault.credentials).toBeDefined();
    });
  });

  describe("via AgentVault.vault()", () => {
    it("has the vault name set", () => {
      const av = new AgentVault({ token: "agent-token" });
      const vault = av.vault("production");
      expect(vault.name).toBe("production");
    });

    it("has sessions resource wired up", () => {
      const av = new AgentVault({ token: "agent-token" });
      const vault = av.vault("production");
      expect(vault.sessions).toBeDefined();
    });

    it("has services resource wired up", () => {
      const av = new AgentVault({ token: "agent-token" });
      const vault = av.vault("production");
      expect(vault.services).toBeDefined();
    });

    it("has credentials resource wired up", () => {
      const av = new AgentVault({ token: "agent-token" });
      const vault = av.vault("production");
      expect(vault.credentials).toBeDefined();
    });

    it("exposes _httpClient for future resource extensions", () => {
      const av = new AgentVault({ token: "agent-token" });
      const vault = av.vault("production");
      expect(vault._httpClient).toBeDefined();
    });
  });
});
